import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.isAvailableLocale
 */
public class LocaleUtils_isAvailableLocale_TriageGen0Test {

    @Test
    public void testIsAvailableLocale_WithAvailableLocale() {
        // Get a locale that is guaranteed to be in the available set via the class's own method
        Locale availableLocale = LocaleUtils.availableLocaleList().isEmpty() 
            ? Locale.ENGLISH 
            : LocaleUtils.availableLocaleList().get(0);

        // If the list is empty, we can't guarantee success, but based on the implementation,
        // if we pick from the list, it MUST return true.
        if (!LocaleUtils.availableLocaleList().isEmpty()) {
            assertTrue("Expected locale should be available", LocaleUtils.isAvailableLocale(availableLocale));
        }
    }

    @Test
    public void testIsAvailableLocale_WithUnavailableLocale() {
        // Create a locale that is highly unlikely to be in the available set
        // Using a combination of private use tags or unlikely language/country pairs
        Locale unavailableLocale = new Locale("zz", "zz");

        // If the locale is not in the set, it must return false
        // We verify this by ensuring it's not in the available list first
        if (!LocaleUtils.availableLocaleSet().contains(unavailableLocale)) {
            assertFalse("Expected locale should not be available", LocaleUtils.isAvailableLocale(unavailableLocale));
        }
    }

    @Test
    public void testIsAvailableLocale_WithNull() {
        // Testing null input. Since the method calls .contains(locale), 
        // most Set implementations (like HashSet) allow one null, 
        // but if the internal set is a TreeSet or similar, it might throw NPE.
        // However, according to standard Commons Lang behavior for this method:
        try {
            boolean result = LocaleUtils.isAvailableLocale(null);
            // If it doesn't throw, we check the result (usually false if null isn't in set)
            assertFalse("isAvailableLocale(null) should return false if null is not in set", result);
        } catch (NullPointerException e) {
            // If the implementation throws NPE on null, this is also a valid branch/behavior
        }
    }

    @Test
    public void testIsAvailableLocale_BoundaryCases() {
        // Test with common locales
        Locale us = Locale.US;
        Locale uk = Locale.UK;

        // We don't know for sure if US is in the specific JVM's available set,
        // so we use the set itself to drive the test for 100% branch coverage.
        for (Locale loc : LocaleUtils.availableLocaleSet()) {
            assertTrue("Locale from set must return true", LocaleUtils.isAvailableLocale(loc));
        }
    }
}
